[CmdletBinding()]
param(
    [Parameter(Mandatory)][string[]]$Path,
    [string]$Revision = '6071b2d6750b875864ce11011f1aff26243f29e6'
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$repo = '<repo>'
Set-Location -LiteralPath $repo
$tmp = [System.IO.Path]::GetTempFileName()
try {
    foreach ($rel in $Path) {
        $full = Join-Path $repo $rel
        $work = if (Test-Path -LiteralPath $full) { (Get-FileHash -LiteralPath $full -Algorithm SHA256).Hash } else { 'MISSING' }
        $mtime = if (Test-Path -LiteralPath $full) { (Get-Item -LiteralPath $full).LastWriteTime.ToString('s') } else { '' }
        $psi = [System.Diagnostics.ProcessStartInfo]::new('git')
        $psi.ArgumentList.Add('show')
        $psi.ArgumentList.Add("$Revision`:$rel")
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.WorkingDirectory = $repo
        $p = [System.Diagnostics.Process]::Start($psi)
        $fs = [System.IO.File]::Create($tmp)
        try { $p.StandardOutput.BaseStream.CopyTo($fs) } finally { $fs.Dispose() }
        $p.WaitForExit()
        $blob = if ($p.ExitCode -eq 0) { (Get-FileHash -LiteralPath $tmp -Algorithm SHA256).Hash } else { 'NOT-IN-REVISION' }
        '{0} work={1} blob={2} mtime={3}' -f $rel, $work, $blob, $mtime
    }
} finally { Remove-Item -LiteralPath $tmp -Force }

