[CmdletBinding()]
param(
    [ValidateSet('Summary', 'Log', 'Bodies', 'Diff', 'Show', 'FileAt', 'NameStatus', 'Status', 'FileLog', 'Tracked', 'Grep')]
    [string]$Mode = 'Summary',
    [string]$From = '8e2f62417e0fe46cefd884e8a61024b12860a2cf',
    [string]$To = '6071b2d6750b875864ce11011f1aff26243f29e6',
    [string[]]$File = @(),
    [string]$Pattern = ''
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$repo = '<repo>'
Set-Location -LiteralPath $repo
$files = @($File | ForEach-Object { $_ -split ',' } | Where-Object { $_ })

switch ($Mode) {
    'Summary' {
        'HEAD=' + (git rev-parse HEAD)
        'BRANCH=' + (git rev-parse --abbrev-ref HEAD)
        'STATUS-TRACKED-CHANGES=' + @(git status --porcelain --untracked-files=no).Count
        'UNTRACKED=' + @(git status --porcelain | Where-Object { $_ -like '??*' }).Count
        'RANGE-COMMITS=' + (git rev-list --count "$From..$To")
        git diff --shortstat $From $To
    }
    'Status' { git status --porcelain --untracked-files=all }
    'Log' { git log --format='%H %cI %aI %s' "$From..$To" }
    'Bodies' { git log --format='=== %H %cI%n%B' "$From..$To" }
    'NameStatus' { git diff --name-status $From $To }
    'Diff' {
        if ($files.Count -gt 0) { git diff $From $To -- @files } else { git diff --stat $From $To }
    }
    'Show' { git show --stat --format='=== %H %cI%n%B' $To }
    'FileAt' {
        foreach ($f in $files) { "=== $To`:$f"; git show "$To`:$f" }
    }
    'FileLog' { git log --format='%H %cI %s' "$From..$To" -- @files }
    'Tracked' { foreach ($f in $files) { $r = git ls-files --error-unmatch -- $f 2>$null; '{0} tracked={1}' -f $f, [bool]$r } }
    'Grep' { git grep -n -I -e $Pattern $To -- @files }
}

